public static void testMax()
{
int actual;
actual = MyUtils.findMax(10, 20);
assert 20 == actual : "value1 < value2";
actual = MyUtils. findMax(5, 5);
assert 5 == actual : "value1 = value2";
actual = MyUtils. findMax(10, 5);
assert 10 == actual : "value1 > value2";
}
